//! Canonical data value reflection retains actual DOMString attributes.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><data id=data value=machine-id>Fallback data</data><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://data-value.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn data_value_canonical_interface_descriptors_and_initial_attribute(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data'),C=HTMLDataElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'value');if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||!a||!a.enumerable||!a.configurable||a.get.length!==0||a.set.length!==1||a.get.name!=='get value'||a.set.name!=='set value'||Object.hasOwn(x,'value')||x.value!=='machine-id'||x.textContent!=='Fallback data')throw 'canonical data metadata';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal data construction';"#);}
#[test]
fn data_value_exact_native_setter_aliases_and_observer_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data'),a=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});x.value='A\ud800Z';var records=watch.takeRecords();if(x.value!=='A\ud800Z'||a.value!==x.value||x.getAttributeNode('value')!==a||records.length!==1||records[0].attributeName!=='value'||records[0].oldValue!=='machine-id'||x.textContent!=='Fallback data')throw 'exact data setter';a.nodeValue='not a date';if(x.value!=='not a date'||a.value!=='not a date')throw 'data is plain reflection';x.removeAttribute('value');if(x.value!==''||a.ownerElement!==null||a.value!=='not a date')throw 'removed value default';"#);}
#[test]
fn data_value_inert_namespace_conversion_and_clone_import_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:data');if(!(x instanceof HTMLDataElement)||x.value!=='')throw 'inert data defaults';var calls=0;x.value={toString:function(){calls++;x.setAttribute('value','author');return 'R\udfffZ';}};if(calls!==1||x.value!=='R\udfffZ'||x.getAttribute('value')!==x.value)throw 'once exact conversion';x.setAttributeNS('urn:foreign','value','foreign');x.setAttributeNS(null,'VALUE','upper');if(x.value!=='R\udfffZ')throw 'null namespace exact local name';var clone=x.cloneNode(false);if(clone.value!==x.value)throw 'namespace clone';x.removeAttributeNS('urn:foreign','value');x.removeAttributeNS(null,'VALUE');var copy=document.importNode(x,false);if(clone.value!==x.value||copy.value!==x.value||copy.ownerDocument!==document||clone.getAttributeNode('value')===x.getAttributeNode('value'))throw 'actual data clone/import';clone.value='independent';if(x.value!=='R\udfffZ'||copy.value!=='R\udfffZ')throw 'independent copied metadata';"#);}


// Exact value metadata preserves conversion, concrete brands and native authority.
#[test]
fn data_value_conversion_reentry_abrupt_symbol_and_current_attr_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data'),old=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});var calls=0;x.value={toString:function(){calls++;x.removeAttribute('value');x.setAttribute('value','replacement');return 'A\ud800Z';}};var current=x.getAttributeNode('value'),records=watch.takeRecords();if(calls!==1||current===old||old.ownerElement!==null||old.value!=='machine-id'||current.value!=='A\ud800Z'||records.length!==3||records[2].oldValue!=='replacement')throw 'current real Attr after conversion';var marker={},caught;try{x.value={toString:function(){x.setAttribute('value','author effect');throw marker;}};}catch(e){caught=e;}records=watch.takeRecords();if(caught!==marker||x.value!=='author effect'||records.length!==1||records[0].oldValue!=='A\ud800Z')throw 'abrupt conversion preserves author effect';caught=false;try{x.value=Symbol('data');}catch(e){caught=e instanceof TypeError;}if(!caught||watch.takeRecords().length||x.value!=='author effect')throw 'Symbol conversion refusal';for(var value of [null,undefined,0,false]){x.value=value;if(x.value!==String(value))throw 'ordinary DOMString conversion';}if(x.textContent!=='Fallback data')throw 'metadata leaves displayed text';"#);
}
#[test]
fn data_value_descriptors_brands_author_override_and_saved_constructor(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data'),C=HTMLDataElement,P=C.prototype,a=Object.getOwnPropertyDescriptor(P,'value'),calls=0;for(var bad of [{},Object.create(P),document.body,document.getElementById('neighbor'),document.createElementNS('urn:foreign','data'),new Document().createElementNS('http://www.w3.org/1999/xhtml','DATA')]){var caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'getter concrete brand';caught=false;try{a.set.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'brand before conversion';}Object.defineProperty(x,'value',{value:'author',writable:true,configurable:true});if(x.value!=='author'||a.get.call(x)!=='machine-id')throw 'canonical authority';a.set.call(x,'canonical');if(x.value!=='author'||x.getAttribute('value')!=='canonical')throw 'borrowed real setter';delete x.value;if(x.value!=='canonical'||Object.hasOwn(x,'value'))throw 'restored inherited reflection';delete window.HTMLDataElement;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P)throw 'saved original interface';"#);
}
#[test]
fn data_value_native_inert_attribute_aliases_namespace_and_exact_copies(){
 for inert in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','data');x.setAttribute('value','machine-id');"}else{"var x=document.getElementById('data');"});run(&mut d,&mut f,&mut p,r#"var a=x.getAttributeNode('value');for(var writer of ['value','nodeValue','textContent']){a[writer]='R\ud800'+writer;if(x.value!=='R\ud800'+writer||x.getAttributeNode('value')!==a)throw 'exact attached alias';}x.setAttributeNS('urn:foreign','value','foreign');x.setAttributeNS(null,'VALUE','upper');if(x.value!=='R\ud800textContent'||x.getAttributeNodeNS(null,'value')!==a)throw 'exact null namespace/local name';x.setAttributeNS(null,'value','no date parsing');if(x.value!=='no date parsing'||a.value!==x.value)throw 'exact null namespace writer';var copy=x.cloneNode(false);if(copy.value!==x.value||copy.getAttributeNode('value')===a)throw 'independent clone';x.removeAttributeNS(null,'value');if(x.value!==''||a.ownerElement!==null||copy.value!=='no date parsing')throw 'removed actual default';"#);}
}
#[test]
fn data_value_native_adoption_and_return_keep_actual_interface_attr_and_child_handles(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data'),attr=x.getAttributeNode('value'),first=x.firstChild,list=x.childNodes,C=HTMLDataElement,doc=new Document();if(doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.parentNode!==null||!(x instanceof C)||x.value!=='machine-id'||attr.ownerElement!==x||attr.ownerDocument!==doc||x.firstChild!==first||x.childNodes!==list)throw 'actual native data adoption';x.value='A\udfffZ';if(document.adoptNode(x)!==x||x.ownerDocument!==document||x.value!=='A\udfffZ'||x.getAttributeNode('value')!==attr)throw 'same native identity return';document.body.appendChild(x);if(x.firstChild!==first||x.childNodes!==list||x.textContent!=='Fallback data'||attr.value!==x.value)throw 'reconnected data source';"#);
}
#[test]
fn data_value_saved_child_origin_precedes_conversion_and_recovers(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var C=frame.contentWindow.HTMLDataElement,a=Object.getOwnPropertyDescriptor(C.prototype,'value'),calls=0;if(C===HTMLDataElement||a.get.call(x)!=='machine-id')throw 'captured data accessor';"#);p.set_location(&crate::navigation::address("https://other-data.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for source in ["a.get.call(x);","a.set.call(x,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://data-value.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'origin precedes conversion';a.set.call(x,'recovered');if(a.get.call(x)!=='recovered')throw 'data origin recovery';");
}

// Shared reflection transactions must refuse before observable changes.
#[test]
fn data_value_writer_refusal_preserves_native_and_inert_records_and_recovers(){
 for inert in [false,true]{for source in [r"x.value='Long canonical \ud800 DateTime replacement';",r"x.setAttribute('value','Long canonical \ud800 DateTime replacement');",r"attr.value='Long canonical \ud800 DateTime replacement';",r"attr.nodeValue='Long canonical \ud800 DateTime replacement';",r"attr.textContent='Long canonical \ud800 DateTime replacement';"]{for mode in 0..5{
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var x=new Document().createElementNS('http://www.w3.org/1999/xhtml','data');x.setAttribute('value','machine-id');"}else{"var x=document.getElementById('data');"});run(&mut d,&mut f,&mut p,"var attr=x.getAttributeNode('value'),watch=new MutationObserver(function(){});watch.observe(x,{attributes:true,attributeOldValue:true});");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("value writer {inert}/{source}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='machine-id'||x.value!=='machine-id'||watch.takeRecords().length)throw 'atomic value writer refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,r"var records=watch.takeRecords();if(x.value!=='Long canonical \ud800 DateTime replacement'||records.length!==1||records[0].oldValue!=='machine-id'||records[0].attributeName!=='value'||x.getAttributeNode('value')!==attr)throw 'fresh value writer recovery';");
 }}}
}
#[test]
fn data_value_reads_enforce_work_copy_string_and_deadline_without_retained_growth(){
 for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let object=if inert{run(&mut d,&mut f,&mut p,r"var data=new Document().createElementNS('http://www.w3.org/1999/xhtml','data');data.value='A\ud800Z';");let Value::Host(object)=p.runtime.execute("data;",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap()else{panic!("inert data handle")};object}else{run(&mut d,&mut f,&mut p,r"document.getElementById('data').value='A\ud800Z';");node_handle((0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("data")).unwrap())};let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.limits.host.string_bytes=1,3=>p.state.execution_deadline=Some(Instant::now()),_=>p.state.retained_limit=p.state.retained};let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.data_value_get(object);if mode==4{assert!(result.is_ok());}else{let e=result.unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("time")||e.contains("bound"),"{e}");}assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.state.execution_deadline=None;p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.begin_job();assert!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.data_value_get(object).is_ok());}}
}

#[test]
fn data_value_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["data"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById(which);");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.value='exact';source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.value='exact';source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('value');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('value')!==oldValue||watch.takeRecords().length)throw 'atomic gauge lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('value')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.value!==source.value||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}


#[test]
fn data_value_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["data"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.value='exact';source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('value');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('value')!==attr||source.value!=='exact'||source.parentNode!==target)throw 'reserved native gauge connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}


#[test]
fn data_value_ordinary_admission_retains_unrelated_raw_name_guards(){
 for tag in ["data"]{let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag:local,attrs,..}=&mut node.kind{if local==tag{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("name".into()),value:DomString::from("seed".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,&format!("var x=document.getElementById('{tag}'),attr=x.getAttributeNode('name'),watch=new MutationObserver(function(){{}});watch.observe(x,{{attributes:true,attributeOldValue:true}});"));
  for source in [r#"x.setAttribute('name','A\ud800z');"#,r#"attr.value='A\ud800z';"#,r#"attr.nodeValue='A\ud800z';"#,r#"attr.textContent='A\ud800z';"#]{let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len());p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(source);assert!(e.contains("Unpaired")||e.contains("requires")||e.contains("support"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len()),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(attr.value!=='seed'||x.getAttributeNode('name')!==attr||watch.takeRecords().length)throw 'raw name guard no prefix';");}
  p.begin_job();run(&mut d,&mut f,&mut p,"x.value='fresh';var records=watch.takeRecords();if(x.value!=='fresh'||attr.value!=='seed'||records.length!==1||records[0].attributeName!=='value')throw 'fresh numeric writer after raw guard';");
 }
}

#[test]
fn data_value_native_deep_clone_import_template_and_fallback_keep_actual_records(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data');x.value='A\ud800Z';var first=x.firstChild,copy=x.cloneNode(true),a=copy.getAttributeNode('value'),list=copy.childNodes;copy.id='copy';document.body.appendChild(copy);if(!(copy instanceof HTMLDataElement)||copy.value!==x.value||copy.firstChild===first||copy.textContent!=='Fallback data'||a===x.getAttributeNode('value'))throw 'actual deep data clone';copy.textContent='Changed\udfff';if(copy.value!==x.value||copy.childNodes!==list||list.length!==1||copy.textContent!=='Changed\udfff'||x.firstChild!==first)throw 'actual data fallback replacement';var doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','data');source.value='I\ud800Z';source.appendChild(doc.createTextNode('Inert fallback'));var imported=document.importNode(source,true);document.body.appendChild(imported);if(imported.value!==source.value||imported.firstChild===source.firstChild||imported.textContent!=='Inert fallback'||source.ownerDocument!==doc)throw 'actual deep data import';var leaf=imported.cloneNode(false),template=document.createElement('template');template.content.appendChild(leaf);document.body.appendChild(template);if(leaf.value!==imported.value||leaf.parentNode!==template.content||leaf.ownerDocument!==template.content.ownerDocument)throw 'actual data template parking';"#);
}
#[test]
fn data_value_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="data"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('data'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','data'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.value!=='machine-id')throw 'active content copy guard';");}
}


#[test]
fn data_value_named_map_methods_keep_ordinary_descriptors_identity_arity_and_brands(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var x=document.getElementById('data'),map=x.attributes,P=NamedNodeMap.prototype,attr=x.getAttributeNode('value'),methods=[];for(var key of ['item','getNamedItem','getNamedItemNS']){var a=Object.getOwnPropertyDescriptor(P,key),method=a.value;methods.push(method);if(typeof method!=='function'||a.get!==undefined||!a.enumerable||!a.writable||!a.configurable||method.name!==key||method.length!==(key==='getNamedItemNS'?2:1)||map[key]!==method)throw 'ordinary attribute map method';var caught=false;try{method.call({},0);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'concrete map brand';caught=false;try{new method();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'map method construction';}if(map.item(0)!==map[0]||map.item(99)!==null||map.getNamedItem('value')!==attr||map.getNamedItemNS(null,'value')!==attr||map.getNamedItem('absent')!==null)throw 'actual attribute map methods';Object.freeze(P);var at=0;for(var key of ['item','getNamedItem','getNamedItemNS']){var a=Object.getOwnPropertyDescriptor(P,key);if(a.value!==methods[at++]||!a.enumerable||a.writable||a.configurable||map[key]!==a.value)throw 'frozen native method identity';}"#);
}
